// src/pages/notifications/NotificationStatsPage.jsx
import React, { useEffect, useMemo, useState } from 'react';
import { useNotifications } from '../../hooks/UseNotifications';

function NotificationStatsPage() {
  const { notifications, loading, error, refresh, getStats } = useNotifications(200);

  const [serverStats, setServerStats] = useState(null);

  useEffect(() => {
    const run = async () => {
      const s = await getStats({ range: 'daily' });
      setServerStats(s); // null이면 fallback
    };
    run();
  }, [getStats]);

  const fallbackStats = useMemo(() => {
    const counter = { total: 0, DANGER: 0, WARNING: 0, SAFE: 0, UNKNOWN: 0 };

    notifications.forEach((n) => {
      counter.total += 1;
      const label = n.aiLabel || 'UNKNOWN';
      if (counter[label] !== undefined) counter[label] += 1;
      else counter.UNKNOWN += 1;
    });

    return counter;
  }, [notifications]);

  return (
    <div className="page-container">
      <h1>알림 통계</h1>

      <button className="btn" onClick={refresh} style={{ marginBottom: 12 }}>
        새로고침
      </button>

      {loading && <p>불러오는 중...</p>}
      {error && <p style={{ color: 'red' }}>오류: {error.message}</p>}

      {!loading && !error && serverStats && (
        <div className="notification-stats">
          <p style={{ color: '#9ca3af' }}>(서버 통계: /alerts/stats)</p>
          <pre>{JSON.stringify(serverStats, null, 2)}</pre>
        </div>
      )}

      {!loading && !error && !serverStats && (
        <div className="notification-stats">
          <p style={{ color: '#9ca3af' }}>(fallback: 최근 알림 목록 기반 계산)</p>
          <p><strong>총 알림 수:</strong> {fallbackStats.total}</p>
          <p><strong>DANGER:</strong> {fallbackStats.DANGER}</p>
          <p><strong>WARNING:</strong> {fallbackStats.WARNING}</p>
          <p><strong>SAFE:</strong> {fallbackStats.SAFE}</p>
          <p><strong>UNKNOWN:</strong> {fallbackStats.UNKNOWN}</p>
        </div>
      )}
    </div>
  );
}

export default NotificationStatsPage;
